WITH recent_shipments AS (SELECT * FROM shipments WHERE cost >= 80 AND carrier IS NOT NULL AND order_id IN (3, 9, 20)), summary AS (SELECT MONTH(shipped_date) AS shipped_month, MAX(shipped_date) AS last_shipped_date, MIN(cost) AS min_cost FROM recent_shipments GROUP BY MONTH(shipped_date)) SELECT * FROM summary WHERE min_cost >= 55 ORDER BY last_shipped_date, shipped_month LIMIT 10
